class Solution {
    public int countGoodRectangles(int[][] rectangles) {
        int maxLen = 0;
        for (int[] r : rectangles) {
            int side = Math.min(r[0], r[1]);
            if (side > maxLen) maxLen = side;
        }
        int count = 0;
        for (int[] r : rectangles) {
            if (Math.min(r[0], r[1]) == maxLen) count++;
        }
        return count;
    }
}

